    task testcase001;

    begin
        test_num = 1;
        $display("\nTest Case %0d: Power-on Reset", test_num);
        reset_dut();
        #1;

        check_outputs(0, 0, 0, 0, 0, 0, 0);
    end
        endtask

    task testcase002;

    begin
        test_num = 2;
        $display("\nTest Case %0d: Write to Reg0", test_num);
        reset_dut();
        address = 4'h0;
        writedata = 32'hAAAA_BBBB;
        write = 1;
        sync = 1;
        @(posedge clk);
