    assign temp = (A1 & ~A2 & ~C1) | (~A1 & A2 & B1) | (~A1 & A2 & B2) | (A1 & A2 & (B1 | B2));

    assign Y = temp & VPWR & ~VGND & VPB & ~VNB;

endmodule

