description:
Design a circuit that implements a CRC32 (Cyclic Redundancy Check) calculator. This module takes an 8-bit input data stream and computes its CRC32 checksum, which is a 32-bit value, based on the provided data. The operation is clock-driven, with the checksum calculation enabled when the 'en' signal is asserted and reset to its initial state on a high 'rst' signal. The final output CRC value is obtained by XORing the computed state with the constant 32'hffffffff, ensuring that the calculation correctly reflects the desired checksum properties.
module top_module(

    crc,

    clk, rst, en, data_in
    );

code:
module top_module(

    crc,

    clk, rst, en, data_in
    );input clk, rst;
    input en;
    input [7:0] data_in;
    output wire [31:0] crc;

    reg [31:0] 	  state;
    assign crc = state ^ 32'hffffffff;
    reg [31:0] 	  temp;

    reg [4:0] 	  i;
    always @(posedge clk)
      if(rst == 1'b1) begin
	  state <= 32'hffffffff;

      end
      else if(en == 1) begin

	  state <= temp;
      end

    always @(*) begin
	temp = state ^ {24'b0, data_in};
	for (i=0;i<8;i=i+1)
	  if((temp & 32'b1) != 0)
	    temp = (temp >> 1) ^ 32'hedb88320;
	  else
	    temp = (temp >> 1);
    end



endmodule

