Design a 4-to-1 multiplexer circuit. The module takes two control inputs (sel) to select one of four data inputs (data0, data1, data2, data3). Depending on the value of sel, the output (out) is assigned the value of the selected data input, effectively routing one of the four inputs to the output based on the selection criteria.
module top_module(
    // Inputs
    input [1:0] sel,
    input data0,
    input data1,
    input data2,
    input data3,
    // Outputs
    output out
);

code:
module top_module(
    // Inputs
    input [1:0] sel,
    input data0,
    input data1,
    input data2,
    input data3,
    // Outputs
    output out
);// Wires
    wire mux_out0;
    wire mux_out1;

    // Multiplexer
    assign mux_out0 = (sel == 2'b00) ? data0 : data1;
    assign mux_out1 = (sel == 2'b01) ? data2 : data3;
    assign out = (sel == 2'b10) ? mux_out0 : mux_out1;

endmodule

