description:
Design a module that computes the even parity bit for an n-bit input and detects parity errors. The module concatenates the input with a parity bit and calculates the parity by performing an XOR operation on the input signals. It counts the number of '1's in the input, adds the parity bit to this count, and checks whether the total is even or odd. An output signal indicates an error when the parity is inconsistent with the expected even parity. This design is useful for error detection in digital communication systems.
module top_module(
  input [n-1:0] in,
  output par_out,
  output err
);

code:
module top_module(
  input [n-1:0] in,
  output par_out,
  output err
);parameter n = 8; // number of input signals

wire [n-1:0] in_and_par; // input and parity bit
wire [n-1:0] in_xor_par; // input xor parity bit
wire [n-1:0] in_count; // count of 1's in input
wire [n-1:0] par_count; // count of 1's in input plus parity bit

assign in_and_par = {in, par_out}; // concatenate input and parity bit
assign in_xor_par = in ^ par_out; // xor input and parity bit

// count number of 1's in input
genvar i;
generate
  for (i = 0; i < n; i = i + 1) begin : count_ones_input
    assign in_count[i] = in[i];
  end
endgenerate

// Initialize par_count to zero
assign par_count[0] = 1'b0;

// count number of 1's in input plus parity bit
generate
  for (i = 0; i < n; i = i + 1) begin : count_ones_parity
    assign par_count[0] = par_count[0] + in_xor_par[i];
  end
endgenerate

// generate parity bit
assign par_out = ~par_count[0];

// check parity
assign err = par_count[0] % 2;

endmodule

